select

from safety_build_auto_dept sbil
left join safety_build_device sbd on sbil.DEVICE_CODE = sbd.DEVICE_CODE
left join safety_build_process sbp on sbil.BPM_FLOW_ID = sbp.BPM_FLOW_ID
left join safety_group_info sgi on sbil.DEPT_CODE = sgi.code and sgi.status = 'Y'
where 1 = 1 and sbd.DEVICE_STATUS = 1 and sbd.REMOVE_FLAG = 0 and sgi.org_code_path != ''


  order by ${orderByClause}




      limit ${offset}, ${limit}


      limit ${limit}
